// icons -- the BackupCraft style's vector icons (Style::paint_icon): the art of icons_data.rs
// (generated by mkicons.py) drawn with ui::paint_svg_icon; other code points fall back to the
// symbol font

#[path = "icons_data.rs"]
mod icons_data;

/// draw icon cp into its em box (x, y px, size_fx 24.8) -> false: not ours
pub(crate) fn paint(g: &mut ui::Gfx, cp: u32, x: i32, y: i32, size_fx: i32, color: u32, accent: u32) -> bool {
    let Some((art, stroke)) = icons_data::art(cp) else { return false };
    ui::paint_svg_icon2(g, art, x, y, size_fx, color, accent, stroke)
}
